import React, {useState} from "react";
import AddTasks from "./AddTasks";
import DisplayTasks from "./DisplayTasks";
import {useReducer} from "react";
import ToDoReducer from "./ToDoReducer";
import {UserContext} from "./UserContext";
import {Paper, Box, Card, TextField, Grid, Typography, CardContent, Stack, Button, Divider, Breadcrumbs, Chip} from "@mui/material";

import ChecklistIcon from '@mui/icons-material/Checklist';
import HomeIcon from '@mui/icons-material/Home';
import {useNavigate} from "react-router-dom";
import NavigateNextIcon from "@mui/icons-material/NavigateNext";
import PersonAddIcon from "@mui/icons-material/PersonAdd";


export default function SampleToDo({user}){
    // const [tasks, setTasks] = useState([]);
    const [count, setCount] = useState(0);
    const [tasks, dispatch] = useReducer(ToDoReducer,  []);
    const navigate = useNavigate();
    const addTask = (value) => {
            if (value !== ''){
            setCount(count => count+1);
            // setTasks([
            //     ...tasks,
            //     {
            //         id: count,
            //         todo:value,
            //         complete:false
            //     }
            // ]);
            dispatch({
                type: 'add',
                id: count,
                todo: value
            });
            }
    }

    function editTask(task){
        // setTasks(tasks.map((item) => {
        //   if (item.id === task.id){
        //       return task
        //   }else{
        //       return item
        //   }
        //
        // }))
        console.log(task);
        dispatch({
            type: 'edit',
            task: task
        })
    }

    function deleteTask(id){
        // setTasks(tasks.filter((item)=>{return item.id !== id}));
        dispatch({
            type: 'delete',
            id: id
        })
    }

    return(
        <UserContext.Provider value={user}>
            <Stack sx={{
                flexGrow: 1, width: '100%', maxWidth: '900px', mx: 'auto',
                pt: { xs: 2, md: 4 }, pb: { xs: 8, md: 12 }
            }}>

                <Box sx={{ mb: 4 }}>
                    <Typography variant="h3" sx={{ fontWeight: 800, letterSpacing: '-0.02em', mb: 1 }}>
                        Tasks Manager
                    </Typography>
                    <Breadcrumbs separator={<NavigateNextIcon fontSize="small" />}>
                        <Chip
                            label="Home"
                            size="small"
                            icon={<HomeIcon fontSize="small" />}
                            onClick={() => navigate("/")}
                            sx={{ px: 1, cursor: 'pointer', bgcolor: 'transparent', border: '1px solid', borderColor: 'divider' }}

                        />
                        <Chip
                            label="TODO List"
                            size="small"
                            color="primary"
                            icon={<ChecklistIcon fontSize="small" />}
                            onClick={() => {navigate("/checktodo")}}
                            sx={{ px: 1, fontWeight: 600 }}
                        />
                    </Breadcrumbs>
                </Box>

                <Divider sx={{ mb: 6, opacity: 0.6 }} />


                <Stack spacing={4}>
                <AddTasks addTask={addTask}/>
                    <DisplayTasks tasks={tasks} editTask={editTask} deleteTask={deleteTask}/>
                </Stack>
            </Stack>
        </UserContext.Provider>
    )


}