import {LlmInference, FilesetResolver, LlmInferenceOptions} from "@mediapipe/tasks-genai";


let llminfer = null;

export const initLLMInfer = async(modelpath) => {
    if (llminfer) {return llminfer;}
    const genai = await FilesetResolver.forGenAiTasks(
            "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-genai@latest/wasm"
                // '@mediapipe/tasks-genai@latest/wasm'
        );

        llminfer = await LlmInference.createFromOptions(
            genai, {
                baseOptions: {
                    modelAssetPath: modelpath
                },
                maxTokens: 1000,
                topK: 40,
                temperature: 0.8,
                randomSeed: 101
            });

        return llminfer;

}