import React, { useState } from "react";
import {
    Paper, Box, Grid, Typography, Stack, Button, Divider,
    FormControl, InputLabel, Select, MenuItem, Breadcrumbs, Chip,
    alpha, useTheme
} from "@mui/material";
import {
    Home as HomeIcon,
    LocalGroceryStore as LocalGroceryStoreIcon,
    NavigateNext as NavigateNextIcon,
    CheckCircle as CheckCircleIcon,
    AddShoppingCart as AddIcon,
    RestartAlt as ResetIcon
} from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { orderActions } from "./provider";
import { uuid } from "./uuid4";


export default function Drip(){
    const theme = useTheme();
    const navigate = useNavigate();
    const dispatch = useDispatch();

    // Mapping to your Redux state
    const currentItem = useSelector(state => state.orderitems.currentItem);
    const orderItems = useSelector(state => state.orderitems.items);
    const order = useSelector(state => state.orderitems.order);

    const user = useSelector(state => state.userInfo.user);


    const [orderPlaced, setOrderPlaced] = useState('');


    // Explicitly using your defined helper functions
    const addItem = (id, temp) => dispatch(orderActions.addItem({ id, temp }));
    const updateItem = () => dispatch(orderActions.updateItem({})); // Pushes currentItem to items
    const removeItem = () => dispatch(orderActions.removeItem({})); // Clears currentItem
    const updateOrder = (items, orderData) => dispatch(orderActions.updateOrder({ items, order: orderData }));

    const handleFieldChange = (field, value) => {
        const id = currentItem.id || uuid();
        addItem(id, { [field]: value });
    };



    const updateCurrent= (field,e) => {
        if (Object.keys(currentItem).length === 0) {
            addItem(uuid(), {[field]: e});
        } else {
            addItem(currentItem.id, {[field]: e});
        }
    };

    const request = {
        method : 'POST',
        headers: {
            "Content-Type" : "application/json",
            "Access-Control-Request-Headers": "*",
            "Access-Control-Request-Methods": "OPTIONS, POST,PUT, DELETE",

        },
        body: JSON.stringify(orderItems),

    };
    const confirmOrder = () => {
        // Mocking the API response structure expected by your updateOrder reducer
        const mockResponse = {
            order: Math.floor(100000 + Math.random() * 900000),
            order_type: 'Beverages',
            customer_name: user.name,
            items: orderItems
        };
        updateOrder([], mockResponse);
        setOrderPlaced(true);
    };
    return(
        <Stack sx={{ flexGrow: 1, width: '100%', maxWidth: '1000px', mx: 'auto', pt: 4, pb: 12 }}>
            <Box sx={{ mb: 4 }}>
                <Typography variant="h3" sx={{ fontWeight: 800, mb: 1 }}>Drip Coffee</Typography>
                <Breadcrumbs separator={<NavigateNextIcon fontSize="small" />}>
                    <Chip label="Home" size="small" icon={<HomeIcon />} onClick={() => navigate("/")} sx={{ cursor: 'pointer' }} />
                    <Chip label="Coffee Shop" size="small" onClick={() => {navigate("/order")}} color="primary" icon={<LocalGroceryStoreIcon />}   sx={{ px: 1, fontWeight: 600,borderColor: 'primary.main' }}/>
                </Breadcrumbs>
            </Box>

            <Divider sx={{ mb: 6, opacity: 0.6 }} />

            {/* Post-Order Summary */}
            {Object.keys(order).length !== 0 && (
                <Paper variant="outlined" sx={{ p: 4, mb: 4, borderRadius: 4, textAlign: 'center', bgcolor: alpha(theme.palette.success.main, 0.02) }}>
                    <CheckCircleIcon color="success" sx={{ fontSize: 48, mb: 1 }} />
                    <Typography variant="h5" sx={{ fontWeight: 800 }}>Order ID: #{order.order}</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>{order.order_type} Confirmed</Typography>
                    {order.items?.map((item, i) => (
                        <Typography key={i} variant="body1">☕ {item.size} {item.type}</Typography>
                    ))}
                </Paper>
            )}

            <Grid container spacing={4}>
                {/* Selector Section */}
                <Grid item xs={12} md={7}>
                    <Stack spacing={3}>
                        <Paper sx={{ p: 3, borderRadius: 3, border: '1px solid', borderColor: 'divider' }}>
                            <Typography variant="overline" sx={{ fontWeight: 800, color: 'primary.main' }}>Step 1: Beverage</Typography>
                            <FormControl fullWidth sx={{ mt: 1 }}>
                                <InputLabel>Drink Type</InputLabel>
                                <Select
                                    value={currentItem.type || "None"}
                                    label="Drink Type"
                                    onChange={(e) => handleFieldChange("type", e.target.value)}
                                >
                                    <MenuItem value="None"><em>None</em></MenuItem>
                                    <MenuItem value="Coffee">Coffee</MenuItem>
                                    <MenuItem value="Tea">Tea</MenuItem>
                                    <MenuItem value="Something Else">Something Else</MenuItem>
                                </Select>
                            </FormControl>
                        </Paper>

                        <Paper sx={{ p: 3, borderRadius: 3, border: '1px solid', borderColor: 'divider' }}>
                            <Typography variant="overline" sx={{ fontWeight: 800, color: 'primary.main' }}>Step 2: Size</Typography>
                            <FormControl fullWidth sx={{ mt: 1 }}>
                                <InputLabel>Size</InputLabel>
                                <Select
                                    value={currentItem.size || "None"}
                                    label="Size"
                                    onChange={(e) => handleFieldChange("size", e.target.value)}
                                >
                                    <MenuItem value="None"><em>None</em></MenuItem>
                                    <MenuItem value="Small">Small</MenuItem>
                                    <MenuItem value="Medium">Medium</MenuItem>
                                    <MenuItem value="Large">Large</MenuItem>
                                </Select>
                            </FormControl>
                        </Paper>

                        {currentItem.type && currentItem.size && (
                            <Stack direction="row" spacing={2}>
                                <Button fullWidth variant="contained" startIcon={<AddIcon />} onClick={updateItem} sx={{ py: 1.5, borderRadius: 2 }}>
                                    Add to Cart
                                </Button>
                                <Button variant="outlined" startIcon={<ResetIcon />} onClick={removeItem} color="inherit">
                                    Clear
                                </Button>
                            </Stack>
                        )}
                    </Stack>
                </Grid>

                {/* Cart Section */}
                <Grid item xs={12} md={5}>
                    <Paper elevation={0} sx={{ p: 4, borderRadius: 4, border: '1px solid', borderColor: 'divider', bgcolor: alpha(theme.palette.primary.main, 0.02) }}>
                        <Typography variant="h6" sx={{ fontWeight: 800, mb: 2 }}>Shopping Cart</Typography>
                        {orderItems.length > 0 ? (
                            <Stack spacing={2}>
                                {orderItems.map((item, idx) => (
                                    <Box key={idx} sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                        <Typography variant="body2"><b>{item.type}</b> ({item.size})</Typography>
                                    </Box>
                                ))}
                                <Divider sx={{ my: 1 }} />
                                <Button fullWidth variant="contained" onClick={confirmOrder} sx={{ mt: 2, borderRadius: 2 }}>
                                    Confirm Checkout
                                </Button>
                            </Stack>
                        ) : (
                            <Typography variant="body2" color="text.disabled">No items added yet.</Typography>
                        )}
                    </Paper>
                </Grid>
            </Grid>
        </Stack>
    )
}