import React, {useEffect, useRef, useState} from "react";

import IndividualItems from "./IndividualItems";
import ShowSearch from "./ShowSearch";
import {
    Box,
    Stack,
    Grid,
    Button,
    Paper,
    TextField,
    Card,
    CardContent,
    CardActions,
    Typography,
    ImageList, ImageListItem
} from "@mui/material";
import ListSubheader from "@mui/material/ListSubheader";
import ProductItem from "./ProductItem";
import RefreshIcon from "@mui/icons-material/Refresh";


export default function ShopApiItems({results, errorMsg, fetchError, handleRefresh}){
    const [keys, setKeys] = useState();
    const [displayItems, setDisplayItems] = useState(results);
    const searchItems = (keys, items) => {

        if (keys === undefined) {
            setDisplayItems(results);
            return;
        }
        const filteredItems = results.filter(i=> i['item_name'].toLowerCase().startsWith(keys.toLowerCase()));
        setDisplayItems(filteredItems);
        // return  results.filter(i=> i['description'].toLowerCase().startsWith(keys.toLowerCase()));
    }

    useEffect(() => {
        console.log("Loading...", results);
        setDisplayItems(results);
    },[results]);

    const callRefresh = (e) => {setKeys(undefined);handleRefresh();}

    return(
        <Box>

            {  errorMsg  ? (
                    <Card variant="outlined" sx={{ borderRadius: 4, textAlign: 'center', p: 4, borderColor: 'error.light' }}>
                        <CardContent>
                            <Typography variant="h5" sx={{ fontWeight: 800, color: 'error.main', mb: 1 }}>
                                Error Fetching Info
                            </Typography>
                            <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                                We faced an issue retrieving the catalog. Please try again.
                            </Typography>
                            <Box component="img" src="giphy.gif" sx={{ maxWidth: '200px', borderRadius: 2, mb: 2 }} />
                        </CardContent>
                        <CardActions sx={{ justifyContent: 'center' }}>
                            <Button variant="contained" color="error" onClick={callRefresh} startIcon={<RefreshIcon />}>
                                Refresh List
                            </Button>
                        </CardActions>
                </Card>

            ) : (
                <Stack spacing={4}>
                    {/* Controls Bar */}
                    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} justifyContent="space-between" alignItems="center">
                        <Box sx={{ width: { xs: '100%', sm: '400px' } }}>
                            <ShowSearch handleSearch={searchItems} />
                        </Box>
                        <Button
                            variant="outlined"
                            onClick={handleRefresh}
                            startIcon={<RefreshIcon />}
                            sx={{ borderRadius: 2, fontWeight: 600, px: 3 }}
                        >
                            Sync Catalog
                        </Button>
                    </Stack>

                    <Grid container spacing={3}>
                        {displayItems.length > 0 ? (
                            displayItems.map((item) => (
                                <Grid item xs={12} sm={6} md={4} lg={3} key={item.id}>
                                    <ProductItem item={item} />
                                </Grid>
                            ))
                        ) : (
                            <Grid item xs={12}>
                                <Typography variant="body1" color="text.secondary" sx={{ textAlign: 'center', py: 8 }}>
                                    No products found matching your search.
                                </Typography>
                            </Grid>
                        )}
                    </Grid>
                </Stack>
            )
            }
        </Box>
   )

}