import React from "react";
import { Stack, Box, Typography, alpha, useTheme } from "@mui/material";

import ToDoTask from "./ToDoTask";


export default function DisplayTasks({tasks, deleteTask, editTask}){
    const theme = useTheme();


    return(

        <Box sx={{ mt: 2 }}>
            {tasks.length > 0 ? (
                <Stack spacing={1}>
                    {tasks.map((item) => (
                        <ToDoTask
                            key={item.id}
                            item={item}
                            editTask={editTask}
                            deleteTask={deleteTask}
                        />
                    ))}
                </Stack>
            ) : (
                <Box
                    sx={{
                        py: 8,
                        textAlign: 'center',
                        borderRadius: 4,
                        border: '2px dashed',
                        borderColor: 'divider',
                        bgcolor: alpha(theme.palette.action.hover, 0.02)
                    }}
                >
                    <Typography variant="body1" color="text.secondary" sx={{ fontWeight: 500 }}>
                        No active tasks in your backlog.
                    </Typography>
                    <Typography variant="caption" color="text.disabled">
                        Add a task above to get started with your sprint.
                    </Typography>
                </Box>
            )}
        </Box>
    );
}