import React, {useState} from "react";
import SearchIcon from "@mui/icons-material/Search";
import {TextField, Box, Paper} from "@mui/material";
import InputAdornment from "@mui/material/InputAdornment";
import dbclient from "./dbclient";
import Autocomplete from "@mui/material/Autocomplete";

export default function ShowSearch({handleSearch, showBox}){
    const[key, setKey] = useState();
    const[results, setResults] = useState([]);
    const [open, setOpen] = useState(false);

    const doSearch = (e) => {
        setKey(e.target.value)
        if (showBox){
            // apiSearch(e.target.value);
            search(e.target.value).then((resp)=>{
                console.log(resp);
                setResults(resp.data.map(item => item['item_name']));
            }).catch((err)=>{
                console.log(err);
            });
        }else{
            handleSearch(e.target.value);
        }

    }

    async function search(key){
        if (dbclient !== undefined){
            dbclient.from("items").select().textSearch('item_description', key,{type:'websearch'});
        }
        return {};
    }


    const request = {
        method: 'GET',
        header: {
            "Content-Type":"application/json"
        }
    }
    let reqUrl = 'http://localhost:8080/search/suggest'

    function apiSearch(keyword){
        if (keyword.length < 4){
            return;
        }
        const resp = makeAPiCall(keyword);
        resp.then(resp =>{
           setResults([...resp]);
        }).catch(err => {
            console.log(err);
        })
    }
    async function makeAPiCall (keyword) {
        reqUrl = reqUrl + '?' + "keyword="+ keyword
        return await fetch(reqUrl, request).then(resp => {
            if (!resp.ok) {
                throw resp;
            }
            return resp.json()
        }).catch(err => {
            console.log(err);
        });
    }


    return(
        <>

                { showBox ? (
                        <>
                            <Paper variant={ "filled"}
                                   sx={{  align: 'center', width: '60%' }}>
                                {
                                    results.length === 0 ? (
                                        <TextField
                                            id="filled-search"
                                            type={"search"}
                                            slotProps={{
                                                input: {
                                                    startAdornment: <InputAdornment position="start">
                                                        <SearchIcon  ></SearchIcon>
                                                    </InputAdornment>,
                                                },
                                            }}
                                            label="Search"
                                            onChange={(e) => doSearch(e)}
                                            variant={ "filled"}
                                            sx={{  align: 'center', width: '100%' }}
                                        />
                                    ) :(
                                        <Autocomplete
                                            open={{open}}
                                            onOpen={() => setOpen(true)}
                                            onClose={() => setOpen(false)}
                                            disablePortal
                                            options={results}
                                            sx={{  align: 'center', width: '100%' }}
                                            renderInput={(params) =>
                                                <TextField id="filled-text`search" {...params} label="Search" variant={ "filled"} type={"search"} onChange={(e) => doSearch(e)} />}
                                        />
                                    )
                                }

                            </Paper>

                            {/*<div className="vr"/>*/}
                            {/*{ results.length >0 ? (*/}
                            {/*            results.map(item =>{*/}
                            {/*           return <p>{item}</p>*/}
                            {/*        })*/}
                            {/*    ):("")*/}
                            {/*}*/}


                        </>
                ) :(

                    <TextField
                        id="filled-search"
                        type={"search"}
                        slotProps={{
                            input: {
                                startAdornment: <InputAdornment position="start">
                                    <SearchIcon  ></SearchIcon>
                                </InputAdornment>,
                            },
                        }}
                        sx={{ flexGrow: 0, minWidth:300 , alignItems: 'left', px: 0 }}
                        label="Search"
                        onChange={(e) => doSearch(e)}
                        variant={ "filled"}
                    />


                )
                }
        </>

    );
}