import {createClient} from "@supabase/supabase-js";
import {CONFIG} from "./config";
const DATABASE_URL = CONFIG.supabase.url;
const DATABASE_KEY = CONFIG.supabase.anonKey;

console.log('DB URL', DATABASE_URL);

let dbclient;
try{
    dbclient = createClient(DATABASE_URL, DATABASE_KEY, {
        global: {
            headers: {
                'apikey': CONFIG.supabase.anonKey.trim(),
                'X-Client-Info': 'groot-space-web',
            },
        },
        auth: {
            persistSession: true,
            autoRefreshToken: true,
            detectSessionInUrl: true,
            redirectTo: 'https://grootspace.online/createaccount'
        }});
}catch(e){
    console.error(e);

}
export default dbclient;
