
import {createSlice} from "@reduxjs/toolkit";
export const initialOrderState = {
    items: [],
    currentItem: {},
    order: {}
}

export const initialUserState = {
    login_info: {},
    user:{}
}

export const orderSliceInstance =  createSlice({
    name: 'orderitems',
    initialState: initialOrderState,
    reducers: {
        addItem:  (state, action) =>{
              console.log(action.payload);
                if (Object.keys(state.currentItem).length > 0){
                    state.currentItem = {...state.currentItem,...action.payload.temp };
                }else{
                    state.currentItem = {"id":action.payload.id ,  ...action.payload.temp};
                }
        },
        updateItem:  (state, action) =>{
               state.items.push(state.currentItem);
               state.currentItem = {};
        },
        removeItem: (state,action) => {
            state.currentItem = {};
        },
        updateOrder: (state,action) => {
            console.log("Order Updated:", action.payload.order);
            state.items = action.payload.items;
            state.order = action.payload.order;
        },

    }
});


export const userSliceInstance =  createSlice({
    name: "userInfo",
    initialState: initialUserState,
    reducers: {
        setLogin: (state, action) =>{
            state.login_info = {...state.login_info, ...action.payload}
        },
        updateLoginInfo: (state, action) => {
            console.log("User Info Updated:", action.payload);
            state.user = {...action.payload};
        }
    }
})


export const orderActions = orderSliceInstance.actions;

export const orderReducer = orderSliceInstance.reducer;

export const userActions = userSliceInstance.actions;
export const userReducer = userSliceInstance.reducer;


