import React, { useState, useEffect, useContext } from 'react';
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  IconButton,
  Container,
  Box,
  Avatar,
  Divider,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Paper,
  Fade,
  CssBaseline,
  useTheme,
  Menu,
  MenuItem, Stack, TextField
} from '@mui/material';
import {
  Person as UserIcon,
  Login as LoginIcon,
  Logout as LogoutIcon,
  Settings as SettingsIcon,
  Security as ShieldIcon,
  Dashboard as DashboardIcon,
  Notifications as BellIcon,
  Menu as MenuIcon,
} from '@mui/icons-material';
import { styled, alpha } from '@mui/material/styles';
import { useNavigate, useLocation } from 'react-router-dom';
import { UserContext } from './UserContext';
import dbclient from "./dbclient";


// --- Styled Components ---

const Header = styled(AppBar, {
  shouldForwardProp: (prop) => prop !== 'isScrolled',
})(({ theme, isScrolled }) => ({
  backgroundColor: isScrolled ? alpha('#ffffff', 0.9) : alpha('#ffffff', 0.6),
  backdropFilter: 'blur(12px)',
  boxShadow: isScrolled ? theme.shadows[1] : 'none',
  borderBottom: `1px solid ${theme.palette.divider}`,
  transition: theme.transitions.create(['height', 'box-shadow', 'background-color'], {
    duration: theme.transitions.duration.standard,
  }),
  height: isScrolled ? 64 : 96,
  justifyContent: 'center',
  color: theme.palette.text.primary,
}));

const LogoContainer = styled(Box, {
  shouldForwardProp: (prop) => prop !== 'isScrolled',
})(({ theme, isScrolled }) => ({
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing(1),
  transition: theme.transitions.create(['transform'], {
    duration: theme.transitions.duration.standard,
  }),
  transform: isScrolled ? 'scale(0.9)' : 'scale(1)',
  transformOrigin: 'left center',
  cursor: 'pointer',
}));

const LogoIconBox = styled(Box)(({ theme }) => ({
  width: 40,
  height: 40,
  backgroundColor: theme.palette.primary.main,
  borderRadius: theme.shape.borderRadius,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  color: '#fff',
  fontWeight: 'bold',
  fontSize: '1.25rem',
}));

const NavLink = styled(Button, {
  shouldForwardProp: (prop) => prop !== 'isActive' && prop !== 'isSpecial',
})(({ theme, isActive, isSpecial }) => ({
  color: isActive ? theme.palette.primary.main : theme.palette.text.secondary,
  fontWeight: isActive ? 700 : 500,
  textTransform: 'none',
  fontSize: '0.95rem',
  padding: '8px 16px',
  borderRadius: isSpecial ? '50px' : '8px',
  transition: 'all 0.3s ease',
  position: 'relative',

  // Special styling for the 'Create Account' CTA
  ...(isSpecial && {
    backgroundColor: alpha(theme.palette.primary.main, 0.1),
    color: theme.palette.primary.main,
    border: `1px solid ${alpha(theme.palette.primary.main, 0.2)}`,
    padding: '8px 20px',
    '&:hover': {
      backgroundColor: theme.palette.primary.main,
      color: '#fff',
    },
  }),

  // Underline effect for regular links
  ...(!isSpecial && {
    '&::after': {
      content: '""',
      position: 'absolute',
      bottom: 6,
      left: '50%',
      width: isActive ? '40%' : '0%',
      height: '2px',
      backgroundColor: theme.palette.primary.main,
      transition: 'all 0.3s ease',
      transform: 'translateX(-50%)',
    },
    '&:hover': {
      color: theme.palette.primary.main,
      backgroundColor: alpha(theme.palette.primary.main, 0.04),
      '&::after': {
        width: '40%',
      },
    },
  }),
}));

const ProfileButton = styled(IconButton, {
  shouldForwardProp: (prop) => prop !== 'isScrolled' && prop !== 'isLoggedIn',
})(({ theme, isScrolled, isLoggedIn }) => ({
  width: isScrolled ? 40 : 48,
  height: isScrolled ? 40 : 48,
  border: `2px solid ${isLoggedIn ? theme.palette.primary.main : theme.palette.grey[300]}`,
  transition: theme.transitions.create(['width', 'height', 'border-color'], {
    duration: theme.transitions.duration.standard,
  }),
  padding: 0,
  overflow: 'hidden',
  '&:hover': {
    borderColor: theme.palette.primary.light,
  },
}));

const DropdownMenu = styled(Paper)(({ theme }) => ({
  position: 'absolute',
  top: '100%',
  right: 0,
  marginTop: theme.spacing(1.5),
  width: 280,
  borderRadius: theme.shape.borderRadius * 2,
  boxShadow: theme.shadows[10],
  border: `1px solid ${theme.palette.divider}`,
  overflow: 'hidden',
  zIndex: theme.zIndex.modal,
}));

const RoleBadge = styled('span')(({ theme, role }) => ({
  fontSize: '0.65rem',
  textTransform: 'uppercase',
  fontWeight: 'bold',
  padding: '2px 8px',
  borderRadius: 999,
  backgroundColor: role === 'admin' ? theme.palette.warning.light : theme.palette.info.light,
  color: role === 'admin' ? theme.palette.warning.dark : theme.palette.info.dark,
}));

const ContentCard = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(4),
  borderRadius: theme.shape.borderRadius * 3,
  border: `1px solid ${theme.palette.divider}`,
  marginBottom: theme.spacing(4),
  boxShadow: theme.shadows[0],
  transition: theme.transitions.create(['box-shadow'], {
    duration: theme.transitions.duration.short,
  }),
  '&:hover': {
    boxShadow: theme.shadows[4],
  },
}));

/**
 * Main Hero Component
 * Replicates the UI/UX of the provided design using Material UI.
 */
export default function HomeHero() {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [mobileMenuAnchorEl, setMobileMenuAnchorEl] = useState(null);

  // 1. Add state for the login form inside the header
  const [loginData, setLoginData] = useState({ email: '', password: '' });
  const [authLoading, setAuthLoading] = useState(false);
  const [authError, setAuthError] = useState("");



  const theme = useTheme();
  const navigate = useNavigate();
  const location = useLocation();
  const { user, updateUser } = useContext(UserContext);

  // Handle scroll logic
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 50) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const toggleLogin = () => {
    navigate("/");
    updateUser({"userName":"Kalyan", "role":"admin", "id":"1"});
    setIsMenuOpen(false);
  };


  // 3. Implement the real Login function
  const handleHeaderLogin = async (e) => {
    e.preventDefault();
    setAuthLoading(true);
    setAuthError("");

    const { data, error } = await dbclient.auth.signInWithPassword({
      email: loginData.email,
      password: loginData.password,
    });

    if (error) {
      setAuthError(error.message);
    } else {
      setIsMenuOpen(false); // Close menu on success
      // Note: App.js listener will handle updating the context/Redux
    }
    setAuthLoading(false);
  };

  const logout = async () => {
      await dbclient.auth.signOut();
      setIsMenuOpen(false);
      navigate("/");
  }

  const handleMobileMenuOpen = (event) => {
    setMobileMenuAnchorEl(event.currentTarget);
  };

  const handleMobileMenuClose = () => {
    setMobileMenuAnchorEl(null);
  };

  // const isLoggedIn = user && user.id !== "1";
  const isLoggedIn = user && user.id && user.id !== "1";;

  const userRole = user?.role || 'user';
  const isHomePage = location.pathname === "/";
  const isMobileMenuOpen = Boolean(mobileMenuAnchorEl);

  const [hoverTimeout, setHoverTimeout] = useState(null);

  const handleMouseEnter = () => {
    if (hoverTimeout) clearTimeout(hoverTimeout);
    setIsMenuOpen(true);
  };

  const handleMouseLeave = () => {
    // Small delay (200ms) gives the user time to move from the avatar to the menu
    const timeout = setTimeout(() => {
      setIsMenuOpen(false);
    }, 200);
    setHoverTimeout(timeout);
  };

  return (

      <>
      {/* Dynamic Header */}
      <Header position="fixed" isScrolled={isScrolled}>
        <Container maxWidth="xl" sx={{ px: { xs: 2, md: 6 } }}>
          <Toolbar disableGutters sx={{ justifyContent: 'space-between' }}>
            
            {/* Mobile Menu Icon */}
            <Box sx={{ display: { xs: 'flex', md: 'none' } }}>
              <IconButton
                size="large"
                aria-label="menu"
                aria-controls="menu-appbar"
                aria-haspopup="true"
                onClick={handleMobileMenuOpen}
                color="inherit"
              >
                <MenuIcon />
              </IconButton>
              <Menu
                id="menu-appbar"
                anchorEl={mobileMenuAnchorEl}
                anchorOrigin={{
                  vertical: 'bottom',
                  horizontal: 'left',
                }}
                keepMounted
                transformOrigin={{
                  vertical: 'top',
                  horizontal: 'left',
                }}
                open={isMobileMenuOpen}
                onClose={handleMobileMenuClose}
                slotProps={{
                  paper: {
                    sx: {
                      display: { xs: 'block', md: 'none' },
                      width: '260px',
                      mt: 1.5,
                      borderRadius: '16px',
                      border: '1px solid',
                      borderColor: 'divider',
                      boxShadow: '0px 10px 30px rgba(0,0,0,0.08)',
                      p: 1, // Padding for the menu container
                    }
                  }
                }}
                TransitionProps={{ timeout: 400 }}
              >
                {[
                  { label: 'Products', path: '/fetchapis', icon: <DashboardIcon fontSize="small" /> },
                  { label: 'AI Chat', path: '/chat', icon: <BellIcon fontSize="small" /> },
                  { label: 'Create Account', path: '/create', icon: <UserIcon fontSize="small" /> },
                ].map((item) => {
                  const isActive = location.pathname === item.path;

                  return (
                      <MenuItem
                          key={item.path}
                          onClick={() => { navigate(item.path); handleMobileMenuClose(); }}
                          sx={{
                            borderRadius: '10px',
                            mb: 0.5,
                            py: 1.5,
                            display: 'flex',
                            gap: 2,
                            color: isActive ? 'primary.main' : 'text.primary',
                            bgcolor: isActive ? alpha(theme.palette.primary.main, 0.08) : 'transparent',
                            '&:hover': {
                              bgcolor: alpha(theme.palette.primary.main, 0.04),
                            },
                          }}
                      >
                        <ListItemIcon sx={{
                          minWidth: 0,
                          color: isActive ? 'primary.main' : 'text.secondary'
                        }}>
                          {item.icon}
                        </ListItemIcon>
                        <Typography sx={{ fontWeight: isActive ? 700 : 500, fontSize: '0.9rem' }}>
                          {item.label}
                        </Typography>
                      </MenuItem>
                  );
                })}
              </Menu>
            </Box>

            {/* Logo Section */}
            <LogoContainer isScrolled={isScrolled} onClick={() => navigate("/")}>
              <LogoIconBox><img
                  src={"logo512.png"}
                  alt="GrootSpace Logo"
                  style={{ maxWidth: 160 , width: 80, height: 'auto'}} // Use inline styles or makeStyles/sx prop for styling
              />
              </LogoIconBox>
              <Typography variant="h5" component="div" sx={{ color: 'primary.main', fontWeight: 'bold', fontSize: '1.25rem',  display: { xs: 'none', sm: 'block' } }}>
                Groot Space<Typography component="span" sx={{ color: 'primary.main', fontWeight: 'bold' }}>.</Typography>
              </Typography>
            </LogoContainer>

            {/* Desktop Navigation */}
            <Box sx={{ display: { xs: 'none', md: 'flex' }, alignItems: 'center', gap: 2 }}>
              <NavLink
                  isActive={location.pathname === "/fetchapis"}
                  onClick={() => navigate("/fetchapis")}
              >
                Products
              </NavLink>

              <NavLink
                  isActive={location.pathname === "/chat"}
                  onClick={() => navigate("/chat")}
              >
                AI Chat
              </NavLink>

              {/* Separation for the CTA */}
              <Box sx={{ height: 24, width: '1px', bgcolor: 'divider', mx: 1 }} />

              <NavLink
                  isSpecial
                  isActive={location.pathname === "/create"}
                  onClick={() => navigate("/create")}
              >
                Create Account
              </NavLink>
            </Box>

            {/* Profile Section */}
            <Box sx={{ position: 'relative' }}
                 onMouseEnter={handleMouseEnter}
                 onMouseLeave={handleMouseLeave} >
              <ProfileButton 
                isScrolled={isScrolled}
                isLoggedIn={isLoggedIn}
                sx={{ cursor: 'pointer' }}
              >
                {isLoggedIn ? (
                  <Avatar 
                    src="personavatar.png" 
                    alt={user?.userName || "Profile"} 
                    sx={{ width: '100%', height: '100%' }}
                  />
                ) : (
                  <Avatar sx={{ bgcolor: 'transparent', color: 'text.secondary', width: '100%', height: '100%' }}>
                    <UserIcon />
                  </Avatar>
                )}
              </ProfileButton>

              {/* Dynamic Dropdown Menu */}
              <Fade in={isMenuOpen}>
                <Box sx={{
                  position: 'absolute',
                  top: '100%',
                  right: 0,
                  pt: 1.5 // This creates an invisible "bridge" so the mouse stays over the container
                }}>
                <DropdownMenu>
                  {!isLoggedIn ? (
                    <Box sx={{ p: 3 }}>
                      <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 2, fontWeight: 700 }}>Welcome! Please sign in to manage your account.</Typography>
                      <Stack spacing={2}>
                        <TextField
                            size="small"
                            label="Email"
                            fullWidth
                            onChange={(e) => setLoginData({...loginData, email: e.target.value})}
                        />
                        <TextField
                            size="small"
                            label="Password"
                            type="password"
                            fullWidth
                            onChange={(e) => setLoginData({...loginData, password: e.target.value})}
                        />
                        <Button
                            fullWidth
                            variant="contained"
                            disabled={authLoading}
                            onClick={handleHeaderLogin}
                            sx={{ borderRadius: 2, textTransform: 'none', fontWeight: 700 }}
                        >
                          {authLoading ? "Checking..." : "Login"}
                        </Button>
                        <Divider />
                        <Button
                            fullWidth
                            variant="text"
                            size="small"
                            onClick={() => { navigate("/create"); setIsMenuOpen(false); }}
                            sx={{ textTransform: 'none', fontSize: '0.75rem' }}
                        >
                          Don't have an account? Join now
                        </Button>
                      </Stack>
                    </Box>
                  ) : (
                    <>
                      <Box sx={{ px: 2, py: 1.5, borderBottom: 1, borderColor: 'divider' }}>
                        <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>
                          {user.name || "Groot User"}
                        </Typography>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                          <RoleBadge role={user.role || 'user'}>{user.role || 'user'}</RoleBadge>
                          <Typography variant="caption" color="text.secondary">
                            {user.userName}
                          </Typography>
                        </Box>
                      </Box>

                      <List disablePadding>
                        <MenuLink icon={<UserIcon fontSize="small" />} label="My Profile" onClick={() => navigate("/create")} />
                        <MenuLink icon={<SettingsIcon fontSize="small" />} label="Tasks Manager" onClick={() => navigate("/checktodo")} />
                        
                        <Divider sx={{ my: 1 }} />
                        <Typography variant="caption" sx={{ px: 2, fontWeight: 'bold', color: 'text.disabled', textTransform: 'uppercase', letterSpacing: 1 }}>
                            Your Tools
                        </Typography>
                        <MenuLink icon={<DashboardIcon fontSize="small" />} label="Compare" onClick={() => navigate("/compare")} />
                        <MenuLink icon={<ShieldIcon fontSize="small" />} label="Play" onClick={() => navigate("/play")} />
                        <MenuLink icon={<BellIcon fontSize="small" />} label="Order" onClick={() => navigate("/order")} />

                      </List>

                      <Box sx={{ px: 1, py: 1, borderTop: 1, borderColor: 'divider' }}>
                        <Button 
                          fullWidth 
                          onClick={logout}
                          startIcon={<LogoutIcon fontSize="small" />}
                          sx={{ justifyContent: 'flex-start', color: 'error.main', textTransform: 'none', fontSize: '0.875rem', '&:hover': { bgcolor: 'error.50' } }}
                        >
                          Logout
                        </Button>
                      </Box>
                    </>
                  )}
                </DropdownMenu>
                </Box>
              </Fade>
            </Box>
          </Toolbar>
        </Container>
      </Header>

      {/* Main Content */}

      {isHomePage && (
      <Container component="main" maxWidth="lg" sx={{width: '100%',
        flexDirection: 'column',
        display: 'flex', pt: { xs: 12, sm: 14, md: 16, lg: 20 },
        pb: { xs: 8, sm: 10, md: 12, lg: 16}
      }}>
        <Box sx={{ textAlign: 'center', mb: 8 }}>
          <Typography variant="h2" component="h1" sx={{ fontWeight: 800, mb: 3, fontSize: { xs: '2.5rem', md: '3.75rem' }, letterSpacing: '-0.02em', color: 'text.primary' }}>
            Engineering the <Typography component="span" variant="inherit" color="primary" sx={{ fontStyle: 'italic' }}> In-demand Consumer Products.</Typography>          </Typography>
          <Typography variant="h6" color="text.secondary" sx={{ maxWidth: '600px', mx: 'auto', mb: 4, fontWeight: 400 }}>
            We transform complex challenges into scalable digital solutions. From cloud-native architectures to intuitive user experiences, we build software that drives growth.          </Typography>
          <Box sx={{ display: 'flex', justifyContent: 'center', gap: 2 }}>
            <Button variant="contained" size="large" sx={{ borderRadius: 50, px: 4, py: 1.5, textTransform: 'none', fontSize: '1rem', fontWeight: 600, boxShadow: 4 }}>
              Start Your Project
            </Button>
            <Button variant="outlined" size="large"   onClick={() => {navigate("/fetchapis")}}
                    sx={{ borderRadius: 50, px: 4, py: 1.5, textTransform: 'none', fontSize: '1rem', fontWeight: 600, borderColor: 'divider', color: 'text.primary', bgcolor: 'background.paper' }}>
              View Our Portfolio
            </Button>
          </Box>
        </Box>

        {/* Dummy Content Blocks */}
        {[
          { title: "Custom SaaS Development", desc: "End-to-end product engineering from ideation to deployment." },
          { title: "Cloud-Native Infrastructure", desc: "Scalable, resilient systems built on AWS, Docker, and Kubernetes." },
          { title: "AI & Machine Learning", desc: "Integrating intelligent features to automate and optimize workflows." },
          { title: "Legacy Modernization", desc: "Refactoring and scaling existing systems for the modern web." }
        ].map((item, i) => (
          <ContentCard key={i} elevation={0}>
            <Box sx={{ width: 96, height: 16, bgcolor: 'primary.light', borderRadius: 999, mb: 2, opacity: 0.2 }} />
            <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>{item.title}</Typography>
            <Typography variant="body1" color="text.secondary" sx={{ mb: 2 }}>{item.desc}</Typography>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
              <Box sx={{ width: '100%', height: 16, bgcolor: 'grey.100', borderRadius: 1 }} />
              <Box sx={{ width: '100%', height: 16, bgcolor: 'grey.100', borderRadius: 1 }} />
              <Box sx={{ width: '75%', height: 16, bgcolor: 'grey.100', borderRadius: 1 }} />
            </Box>
          </ContentCard>
        ))}

      </Container>
      )}
    </>
  );
}

/**
 * Utility Component for Menu Items
 */
function MenuLink({ icon, label, color = 'text.primary', onClick }) {
  return (
    <ListItem disablePadding>
      <ListItemButton sx={{ py: 1, px: 2 }} onClick={onClick}>
        <ListItemIcon sx={{ minWidth: 36, color: color === 'text.primary' ? 'text.secondary' : color }}>
          {icon}
        </ListItemIcon>
        <ListItemText 
          primary={label} 
          primaryTypographyProps={{ variant: 'body2', color: color }} 
        />
      </ListItemButton>
    </ListItem>
  );
}
