import React, {useState} from "react";
import VideoPlayer from "./VideoPlayer";

import {Box, Stack,  Button , Divider,  Breadcrumbs, Chip} from "@mui/material";

import {Card, CardCover,CardContent, Typography }from "@mui/joy";
import FeaturedVideoIcon from '@mui/icons-material/FeaturedVideo';
import HomeIcon from '@mui/icons-material/Home';
import {useNavigate} from "react-router-dom";


export default function PlaySomeVideo(){
    const [play, setPlay] = useState(false);
    const navigate = useNavigate();

    return(


        <Stack sx={{ flexGrow: 1, flexDirection: 'column', alignItems: 'left', px: 0 }} >
            <Typography variant="h5" component="div" key={"todotype"} sx={{ flexGrow: 1,display: 'flex',  mt: 1, mb: 1  }}>
               Video
            </Typography>

            <Breadcrumbs separator={">"} aria-label="breadcrumb" sx={{ flexGrow: 1,display: 'flex', alignItems: 'center', mt: 1, mb: 1 }}>
                <Chip
                    component="a"
                    label="Home"
                    icon={<HomeIcon fontSize="small" />}
                    onClick={() => {navigate("/")}}
                />

                <Chip
                    component="a"
                    label="Videos"
                    icon={<FeaturedVideoIcon fontSize="small" />}
                    onClick={() => {navigate("/")}}
                >
                    <Typography sx={{ color: 'primary.main' }}>Your TODO</Typography>
                </Chip>


            </Breadcrumbs>
            <VideoPlayer src={"https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4"} isPlaying={play}/>
            <Button key="todoedit"  variant="contained" onClick={() => {setPlay(!play);}}
                    sx={{ flexGrow: 1, display: 'flex', align: 'center' }}>{play?"Stop":"Play"}</Button>



            </Stack>
    );
}