// src/config.js

const getEnv = (key) => {
    const value = process.env[key];

    // Warn the developer if a variable is missing in development
    if (!value && process.env.NODE_ENV !== 'production') {
        console.warn(`⚠️ Environment variable ${key} is missing! Check your .env files.`);
    }

    return value;
};

export const CONFIG = {
    // Supabase Configuration
    supabase: {
        url: getEnv('REACT_APP_DATABASE_URL'),
        anonKey: getEnv('REACT_APP_DATABASE_KEY'),
    },
    chat: {
        modelpath: getEnv('REACT_APP_CHAT_MODEL'),
    },

    // App Settings
    app: {
        name: "Groot Space",
        environment: process.env.NODE_ENV,
        isProduction: process.env.NODE_ENV === 'production',
    },

    // API Routes or other constants
    routes: {
        home: '/',
        createAccount: '/createaccount',
        taskManager: '/taskmanager',
    }
};

export default CONFIG;