import React, {useContext, useState} from "react";
import {UserContext} from "./UserContext";
import {Paper, Box, Card, TextField, Grid, Typography, CardContent, Stack, Button, Divider} from "@mui/material";
import InputAdornment from "@mui/material/InputAdornment";
import AddIcon from '@mui/icons-material/Add';



export default function AddTasks({addTask, tasks}){

    const [text, setText] = useState('');
    const user = useContext(UserContext);

    const handleAdd = () => {
        if (text.trim()) {
            addTask(text);
            setText('');
        }
    };

    return (

        <Stack spacing={2} sx={{ width: '100%' }}>
            <Typography variant="overline" sx={{ fontWeight: 800, color: 'text.secondary', letterSpacing: '0.1em' }}>
                Engineering Backlog for {user.userName || 'Dev'}
            </Typography>
            <Paper elevation={0} sx={{ p: 0.5, borderRadius: '12px', border: '1px solid', borderColor: 'divider' }}>
                <TextField
                    fullWidth
                    placeholder="Capture a new task..."
                    value={text}
                    onChange={(e) => setText(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
                    InputProps={{
                        sx: { px: 2, py: 0.5 },
                        disableUnderline: true,
                        endAdornment: (
                            <InputAdornment position="end">
                                <Button
                                    variant="contained"
                                    onClick={handleAdd}
                                    startIcon={<AddIcon />}
                                    sx={{ borderRadius: '8px', textTransform: 'none', fontWeight: 600 }}
                                >
                                    Add Task
                                </Button>
                            </InputAdornment>
                        ),
                    }}
                    variant="standard"
                />
            </Paper>
        </Stack>

    );
}