import React, {useEffect, useReducer, useRef, useState} from "react";
import {
    Stack,
    Button,
    Paper,
    Divider,
    Grid,
    List,
    ListItem,
    Typography,
    Breadcrumbs,
    Chip,
    Box,
    IconButton, useTheme
} from "@mui/material";



import CompareReducer from "./CompareReducer";

import {useNavigate} from "react-router-dom";

import {
    CloudUpload as CloudUploadIcon,
    Refresh as RefreshIcon,
    Difference as DifferenceIcon,
    Home as HomeIcon,
    NavigateNext as NavigateNextIcon,
    CheckCircle as CheckCircleIcon,
    ErrorOutline as ErrorOutlineIcon
} from "@mui/icons-material";
import {alpha} from "@mui/material/styles";

export default function CompareFiles(){
    // let files = useRef([]);
    const [tasks, dispatch] = useReducer(CompareReducer,  {});
    const [commonItems, setCommonItems] = useState([]);
    const [fileone, setFileone] = useState("");
    const [filetwo, setFiletwo] = useState("");
    const [compared, setCompared] = useState(false);
    const [cnt, setCnt] = useState(1);

    var files;

    const theme = useTheme();
    const navigate = useNavigate();


    const loadFiles = (e, fileIndex) => {
        const fileObj = e.target.files[0];
        if (!fileObj) return;
        if (fileIndex === 1) setFileone(fileObj.name);
        else setFiletwo(fileObj.name);

        let reader = new FileReader();
        reader.readAsText(fileObj);

        reader.onload = (event) =>{
            let content = reader.result.split("\n");
            dispatch({
                type : 'upload',
                file_no: fileIndex,
                name: fileObj.name,
                content: content
            })
        }
        setCnt(cnt+1);
        console.log(tasks);

    }

    const compareFiles = () => {

        dispatch({
            type : 'compare',
            file_no: cnt,
            name: 'diff_file',
            content: '',
        })
        setCompared(true);
    }

    const refreshFiles = () => {

        dispatch({
            type : 'refresh',
            file_no: 0,
            name: '',
            content: '',
        })
        setCompared(false);
    }

    return(

        <Stack sx={{
            flexGrow: 1, width: '100%', maxWidth: '1100px', mx: 'auto',
            pt: { xs: 2, md: 4 }, pb: { xs: 8, md: 12 }
        }}>

            <Box sx={{ mb: 4 }}>
                <Typography variant="h3" sx={{ fontWeight: 800, letterSpacing: '-0.02em', mb: 1 }}>
                    Compare Tool
                </Typography>
                <Breadcrumbs separator={<NavigateNextIcon fontSize="small" />}>
                    <Chip
                        label="Home"
                        size="small"
                        icon={<HomeIcon fontSize="small" />}
                        onClick={() => navigate("/")}
                        sx={{ px: 1, cursor: 'pointer' }}
                    />
                    <Chip
                        label="Compare"
                        size="small"
                        color="primary"
                        icon={<DifferenceIcon fontSize="small" />}
                        onClick={() => {navigate("/compare")}}
                        sx={{ px: 1, fontWeight: 600, borderColor: 'primary.main' }}
                    />
                </Breadcrumbs>
            </Box>


                    <Divider sx={{ mb: 6, opacity: 0.6 }} />

            <Paper variant="outlined" sx={{ p: 3, borderRadius: 4, mb: 4, bgcolor: alpha(theme.palette.primary.main, 0.02) }}>
                <Grid container spacing={3} alignItems="center">
                    <Grid item xs={12} md={4}>
                        <Button
                            fullWidth
                            component="label"
                            variant={fileone ? "outlined" : "contained"}
                            startIcon={<CloudUploadIcon />}
                            sx={{ borderRadius: 2, py: 1.5 }}
                        >
                            {fileone ? `File 1: ${fileone}` : "Upload File 1"}
                            <input type="file" hidden accept=".txt,.pdf" onChange={(e) => loadFiles(e, 1)} />
                        </Button>
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <Button
                            fullWidth
                            component="label"
                            variant={filetwo ? "outlined" : "contained"}
                            startIcon={<CloudUploadIcon />}
                            sx={{ borderRadius: 2, py: 1.5 }}
                        >
                            {filetwo ? `File 2: ${filetwo}` : "Upload File 2"}
                            <input type="file" hidden accept=".txt,.pdf" onChange={(e) => loadFiles(e, 2)} />
                        </Button>
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <Stack direction="row" spacing={1}>
                            <Button
                                fullWidth
                                variant="contained"
                                color="primary"
                                disabled={!fileone || !filetwo || compared}
                                onClick={compareFiles}
                                sx={{ borderRadius: 2, py: 1.5, fontWeight: 700 }}
                            >
                                Compare Now
                            </Button>
                            <IconButton onClick={refreshFiles} color="primary" sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 2 }}>
                                <RefreshIcon />
                            </IconButton>
                        </Stack>
                    </Grid>
                </Grid>

                {compared && (
                    <Box sx={{ mt: 3, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1 }}>
                        {tasks[3]?.content.length === 0 ? (
                            <Chip icon={<CheckCircleIcon />} label="Identical Files: No Differences" color="success" variant="outlined" />
                        ) : (
                            <Chip icon={<ErrorOutlineIcon />} label="Differences Detected" color="error" variant="outlined" />
                        )}
                    </Box>
                )}
            </Paper>

            {/* Comparison Viewports */}
            <Grid container spacing={2}>
                {[1, 2].map((num) => (
                    <Grid item xs={12} md={6} key={num}>
                        <Typography variant="overline" sx={{ fontWeight: 800, color: 'text.secondary', ml: 1 }}>
                            {num === 1 ? fileone || "Source File" : filetwo || "Target File"}
                        </Typography>
                        <Paper
                            variant="outlined"
                            sx={{
                                height: '500px',
                                overflowY: 'auto',
                                borderRadius: 3,
                                bgcolor: 'background.paper',
                                borderTop: '4px solid',
                                borderTopColor: num === 1 ? 'primary.main' : 'secondary.main'
                            }}
                        >
                            <List dense sx={{ p: 0 }}>
                                {tasks[num]?.content ? (
                                    tasks[num].content.map((line, i) => {
                                        const isCommon = tasks[3]?.content.indexOf(line) !== -1;
                                        return (
                                            <ListItem
                                                key={i}
                                                sx={{
                                                    borderBottom: '1px solid',
                                                    borderColor: 'divider',
                                                    bgcolor: isCommon ? alpha(theme.palette.success.light, 0.1) : alpha(theme.palette.error.light, 0.1),
                                                    py: 0.5
                                                }}
                                            >
                                                <Typography variant="code" sx={{
                                                    fontSize: '0.85rem',
                                                    fontFamily: 'monospace',
                                                    color: isCommon ? 'success.dark' : 'error.main'
                                                }}>
                                                    {i + 1}. {line}
                                                </Typography>
                                            </ListItem>
                                        );
                                    })
                                ) : (
                                    <Box sx={{ p: 4, textAlign: 'center', opacity: 0.5 }}>
                                        <Typography variant="body2">No file selected</Typography>
                                    </Box>
                                )}
                            </List>
                        </Paper>
                    </Grid>
                ))}
            </Grid>
            </Stack>

    );
}