import React from "react";

export default function CompareReducer (tasks, actions) {

    if (actions.type === 'upload'){
        return {
            ...tasks,
            [actions.file_no]: {
                name: actions.name,
                content: actions.content
            }
        };
    } else if (actions.type === 'compare'){
        const file1 = tasks[1]?.content || [];
        const file2 = tasks[2]?.content || [];
        const commonLines = file1.filter((line) => {
            const trimmedLine = line.trim();
            // We ignore empty lines to prevent them from being marked as 'matching' everywhere
            if (trimmedLine === "") return false;
            return file2.some(l2 => l2.trim() === trimmedLine);
        });
        return {
            ...tasks,
            3: {
                name: 'comparison_result',
                content: commonLines
            }
        };


    }else if (actions.type === 'refresh'){
        return {};
    }
    else {
        throw Error('Unknown action type' + actions.type)
    }

}
