import React from "react";
import {Card, ListGroup, ListGroupItem} from "react-bootstrap";



export default function IndividualTicker({items}){
    return(
        <>
            <ListGroup>
                {
                    items.map((item) =>
                        <ListGroupItem key={item.payload}>
                                <Card.Body>
                                    {item.payload}
                                </Card.Body>

                        </ListGroupItem>
                    )


                }



            </ListGroup>


        </>

    );
}