import React, {useEffect, useRef, useState} from "react";
import {useNavigate} from "react-router-dom";
import {useContext} from "react";
import {UserContext} from "./UserContext";
import {useDispatch, useSelector} from "react-redux";
import {userActions} from "./provider";
import CircularProgress from "@mui/material/CircularProgress";
import Box from "@mui/material/Box";
import {
    Container, Stack, Button, Paper, TextField, Card, CardContent, Typography, Alert, CardActions, Breadcrumbs, Link,
    Divider, useTheme
} from "@mui/material";
import HomeIcon  from "@mui/icons-material/Home";
import PersonAddIcon from "@mui/icons-material/PersonAdd";
import ManageAccountsIcon from '@mui/icons-material/ManageAccounts';
import NavigateNextIcon from '@mui/icons-material/NavigateNext';


import Chip from "@mui/material/Chip";
import dbclient from "./dbclient";
import {alpha} from "@mui/material/styles";
import SaveIcon from "@mui/icons-material/Save";
import EditIcon from "@mui/icons-material/Edit";
import LoginIcon from "@mui/icons-material/Login";
export default function CreateAccount(){
    const [name, setName] = useState('');
    const {user , updateUser}= useContext(UserContext);
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const theme = useTheme();


    // Profile Logic States
    const isLoggedIn = user && user.id && user.id !== "1"; // "1" was your guest ID
    const [isEditing, setIsEditing] = useState(false);
    const [editName, setEditName] = useState(user?.name || "");


    const setLogin = (temp) => dispatch(userActions.setLogin(temp));
    const updateLoginIfo = (item) => dispatch(userActions.updateLoginInfo(item));

    const [isLoginView, setIsLoginView] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [passwordMatch, setPasswordMatch] = useState(true);
    const [userInfo, setUserInfo] = useState({
        name: "",
        email: "",
        password: "",
        repassword: ""
    });

    // Sync local state with context when user loads
    useEffect(() => {
        if (user?.name) setEditName(user.name);
    }, [user]);

    const handleUpdateName = async () => {
        setLoading(true);
        const { data, error: updateError } = await dbclient.auth.updateUser({
            data: { full_name: editName }
        });

        if (updateError) {
            setError(updateError.message);
        } else {
            updateUser({ ...user, name: editName });
            setIsEditing(false);
        }
        setLoading(false);
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setUserInfo({ ...userInfo, [name]: value });
        if (e.target.name === "repassword" || e.target.name === "password") {
            const currentPass = name === "password" ? value : userInfo.password;
            const currentRePass = name === "repassword" ? value : userInfo.repassword;
            setPasswordMatch(currentPass === currentRePass);
        }
    };


    const handleAuth = async (e) => {
        e.preventDefault();
        setError("");

        const passwordRegex = /^(?=.*[A-Za-z])(?=.*\d).{10,}$/;


        if (!isLoginView) {
            if (!passwordRegex.test(userInfo.password)) {
                setError("Password must be at least 10 characters long and contain both letters and numbers.");
                return;
            }
            if (!passwordMatch) {
                setError("Passwords do not match.");
                return;
            }
        }


        setLoading(true);


        try {
            if (isLoginView) {
                const { error: ae } = await dbclient.auth.signInWithPassword({
                    email: userInfo.email, password: userInfo.password
                });
                if (ae) throw ae;
                navigate("/");
            } else {
                // --- Sign Up New User ---
                if (!passwordMatch) {
                    throw new Error("Passwords do not match.");
                }
                const { error: ae } = await dbclient.auth.signUp({
                    email: userInfo.email, password: userInfo.password,
                    options: { data: { full_name: userInfo.name } }
                });
                if (ae) {
                    // Check if the error is the Supabase Rate Limit
                    if (error.status === 429 || error.message.toLowerCase().includes("rate limit")) {
                        throw new Error("Our daily invite limit has been reached. Please try again after sometime or contact us if the issue persists!");
                    }
                    throw ae;
                }
                alert("Success! Please check your email for a verification link.");
                setIsLoginView(true);
            }

        } catch (err) {
            setError(err.message);
            console.error("Auth Error:", err.message);
        }
        setLoading(false);
    };

    return(

            <Stack sx={{ flexGrow: 1, width:'100%', maxWidth:'600px' ,
                flexDirection: 'column',
                alignItems: 'left',
                pt: { xs: 2, md: 4 },
                pb: { xs: 8, md: 12 },
                mx: 'auto'
            }} >
                <Box sx={{ mb: 4 }}>
                 <Typography variant="h3" component="h1" key={"chattitletypo"}
                             sx={{ fontWeight: 800,
                                 letterSpacing: '-0.02em',
                                 color: 'text.primary',
                                 mb: 1
                    }}>
                     {isLoggedIn ? "Profile" : isLoginView ? "Login" : "Account"}
                    </Typography>
                    <Breadcrumbs separator={<NavigateNextIcon fontSize="small" />} aria-label="breadcrumb"
                                 sx={{ flexGrow: 1,display: 'flex',
                                     color: 'text.secondary', fontSize: '0.875rem',
                                     alignItems: 'center', mt: 1, mb: 1 }}>

                        <Chip
                            component="a"
                            label="Home"
                            icon={<HomeIcon fontSize="small" />}
                            onClick={() => {navigate("/")}}
                            sx={{ px: 1, cursor: 'pointer', bgcolor: 'transparent', border: '1px solid', borderColor: 'divider' }}

                        />

                        <Chip
                            component="a"
                            label={isLoginView ? "Login" : "Create Account"}
                            color="primary"
                            icon={<ManageAccountsIcon fontSize="small" />}
                            onClick={() => {navigate("/create")}}
                            sx={{ px: 1, fontWeight: 600 }}
                        >
                        </Chip>

                    </Breadcrumbs>
                </Box>

                    {error &&
                            <Alert  severity="error" sx={{ mb: 3, borderRadius: 2 }}>
                                {error}
                            </Alert>
                     }
                <Divider sx={{ mb: 6, opacity: 0.6 }} />

                { isLoggedIn ? (
                    /* --- PROFILE MODE: User is logged in --- */
                    <Paper variant="outlined" sx={{ p: 4, borderRadius: 4 }}>
                        <Stack spacing={3}>
                            <Box>
                                <Typography variant="caption" sx={{ fontWeight: 800, color: 'primary.main' }}>EMAIL ADDRESS</Typography>
                                <Typography variant="body1" sx={{ mt: 1, p: 2, bgcolor: alpha(theme.palette.action.hover, 0.05), borderRadius: 2, border: '1px solid', borderColor: 'divider' }}>
                                    {user.userName || user.email}
                                </Typography>
                            </Box>

                            <Box>
                                <Typography variant="caption" sx={{ fontWeight: 800, color: 'primary.main' }}>DISPLAY NAME</Typography>
                                {isEditing ? (
                                    <TextField fullWidth size="small" value={editName} onChange={(e) => setEditName(e.target.value)} sx={{ mt: 1 }} autoFocus />
                                ) : (
                                    <Typography variant="h5" sx={{ mt: 1, fontWeight: 700 }}>{user.name || "Groot User"}</Typography>
                                )}
                            </Box>

                            <Divider />

                            <Button
                                variant={isEditing ? "contained" : "outlined"}
                                startIcon={isEditing ? <SaveIcon /> : <EditIcon />}
                                onClick={isEditing ? handleUpdateName : () => setIsEditing(true)}
                                disabled={loading}
                                sx={{ borderRadius: 2, py: 1.5, fontWeight: 700 }}
                            >
                                {isEditing ? "Save Changes" : "Edit Display Name"}
                            </Button>
                        </Stack>
                    </Paper>
                ) : (
                    /* --- AUTH MODE: Register or Login --- */
                    <Box component="form" noValidate>
                        <Stack spacing={3}>
                            <Typography variant="overline" sx={{ fontWeight: 800, color: 'text.disabled' }}>
                                {isLoginView ? "Enter Credentials" : "Personal Information"}
                            </Typography>

                            {!isLoginView && (
                                <TextField fullWidth required name="name" label="Full Name" onChange={handleChange} variant="outlined" />
                            )}

                            <TextField fullWidth required name="email" label="Email Address" onChange={handleChange} variant="outlined" />

                            <TextField fullWidth required name="password" label="Password" type="password" onChange={handleChange} variant="outlined" helperText={!isLoginView ? "Minimum 10 characters with letters and numbers" : ""} />

                            {!isLoginView && (
                                <TextField
                                    fullWidth required name="repassword" label="Confirm Password" type="password"
                                    error={!passwordMatch} helperText={!passwordMatch && "Passwords do not match"}
                                    onChange={handleChange} variant="outlined"
                                />
                            )}

                            <Button
                                variant="contained" size="large" fullWidth onClick={handleAuth} disabled={loading}
                                startIcon={isLoginView ? <LoginIcon /> : <PersonAddIcon />}
                                sx={{ py: 2, borderRadius: 3, fontWeight: 700, textTransform: 'none', fontSize: '1.1rem' }}
                            >
                                {loading ? "Processing..." : isLoginView ? "Sign In" : "Register Account"}
                            </Button>

                            <Button
                                variant="text" fullWidth onClick={() => setIsLoginView(!isLoginView)}
                                sx={{ fontWeight: 600, textTransform: 'none' }}
                            >
                                {isLoginView ? "Don't have an account? Create one" : "Already have an account? Log in"}
                            </Button>
                        </Stack>
                    </Box>
                )
        }
        </Stack>

    )

}