import React, { useContext, useState } from "react";
import { GameContext } from "./GameContext";
import {
    Stack, Button, Typography, Breadcrumbs, Chip, Divider,
    Box, Grid, Paper, alpha, useTheme
} from "@mui/material";
import {
    Home as HomeIcon,
    SportsEsports as GamesIcon,
    NavigateNext as NavigateNextIcon,
    Refresh as RefreshIcon
} from "@mui/icons-material";
import { useNavigate } from "react-router-dom";


export default function BoardGame(){

    const theme = useTheme();
    const navigate = useNavigate();
    const data = useContext(GameContext);

    // Fallback for board if context isn't ready
    const initialBoard = data?.board || [[0, 0, 0], [0, 0, 0], [0, 0, 0]];
    const [board, setBoard] = useState(initialBoard);
    const [current, setCurrent] = useState(1);
    const [winner, setWinner] = useState(-1);



    const rowSize = board.length;
    // TicTacToe win logic: Player 1 is 1, Player 2 is 2.
    // Win check uses powers to ensure product uniqueness (1^3=1 vs 2^3=8)
    const player1check = Math.pow(1, rowSize);
    const player2check = Math.pow(2, rowSize);


    function resetBoard(){
        setCurrent(1);
        setWinner(-1);
        setBoard(initialBoard);
    }

    function findWinner(temp) {
        // Row Check
        for (let i = 0; i < rowSize; i++) {
            let prod = temp[i].reduce((p, c) => p * c, 1);
            if (prod === player1check) return 1;
            if (prod === player2check) return 2;
        }
        // Column Check
        for (let j = 0; j < rowSize; j++) {
            let prod = temp.map(x => x[j]).reduce((p, c) => p * c, 1);
            if (prod === player1check) return 1;
            if (prod === player2check) return 2;
        }
        // Diagonal Checks
        let leftProd = 1, rightProd = 1;
        for (let i = 0; i < rowSize; i++) {
            leftProd *= temp[i][i];
            rightProd *= temp[i][rowSize - 1 - i];
        }
        if (leftProd === player1check || rightProd === player1check) return 1;
        if (leftProd === player2check || rightProd === player2check) return 2;

        return isBoardFull(temp) ? -2 : -1;
    }

    const isBoardFull = (b) => b.every(row => row.every(cell => cell !== 0));


    function updateBoard(r, c) {
        if (board[r][c] !== 0 || winner !== -1) return;

        const newBoard = board.map((row, rIdx) =>
            row.map((cell, cIdx) => (rIdx === r && cIdx === c ? current : cell))
        );

        setBoard(newBoard);
        setWinner(findWinner(newBoard));
        setCurrent(current === 1 ? 2 : 1);
    }

    // Construct the "disp" variable with modern Paper tiles
    let disp = "";
    if (board) {
        disp = board.map((row, rId) => (
            <Stack key={rId} direction="row" spacing={1} sx={{ mb: 1 }}>
                {row.map((col, cid) => (
                    <Paper
                        key={cid}
                        elevation={0}
                        onClick={() => updateBoard(rId, cid)}
                        sx={{
                            width: 80, height: 80,
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            fontSize: '1.5rem', fontWeight: 900, borderRadius: 2,
                            border: '2px solid',
                            borderColor: col === 0 ? 'divider' : (col === 1 ? 'primary.main' : 'secondary.main'),
                            cursor: col === 0 && winner === -1 ? 'pointer' : 'default',
                            bgcolor: col === 1 ? alpha(theme.palette.primary.main, 0.05) :
                                col === 2 ? alpha(theme.palette.secondary.main, 0.05) : 'background.paper',
                            color: col === 1 ? 'primary.main' : 'secondary.main',
                            transition: 'all 0.2s',
                            '&:hover': {
                                transform: col === 0 && winner === -1 ? 'scale(1.05)' : 'none',
                                borderColor: col === 0 && winner === -1 ? 'primary.main' : ''
                            }
                        }}
                    >
                        {col === 1 ? 'X' : col === 2 ? 'O' : ''}
                    </Paper>
                ))}
            </Stack>
        ));
    }

    return (
        <Stack sx={{
            flexGrow: 1, width: '100%', maxWidth: '900px', mx: 'auto',
            pt: { xs: 2, md: 4 }, pb: { xs: 8, md: 12 }
        }}>
            <Box sx={{ mb: 4 }}>
                <Typography variant="h3" sx={{ fontWeight: 800, mb: 1 }}>Tic-Tac-Toe</Typography>
                <Breadcrumbs separator={<NavigateNextIcon fontSize="small" />}>
                    <Chip
                        label="Home" size="small" icon={<HomeIcon fontSize="small" />}
                        onClick={() => navigate("/")} sx={{ px: 1, cursor: 'pointer' }}
                    />
                    <Chip
                        label="Games" size="small"
                        icon={<GamesIcon fontSize="small" />}
                        onClick={() => {navigate("/play")}}
                        color="primary"
                        sx={{ px: 1, fontWeight: 600, borderColor: 'primary.main' }}
                    />
                </Breadcrumbs>
            </Box>

            <Divider sx={{ mb: 6, opacity: 0.6 }} />

            <Typography variant="subtitle1" sx={{ fontWeight: 800, color: 'text.secondary', textTransform: 'uppercase', mb: 2 }}>
                Current Match
            </Typography>

            <Box sx={{
                p: 4, borderRadius: 4, bgcolor: alpha(theme.palette.primary.main, 0.02),
                border: '1px solid', borderColor: 'divider', textAlign: 'center'
            }}>
                <Typography variant="h5" sx={{
                    fontWeight: 700, mb: 3,
                    color: winner === -1 ? (current === 1 ? 'primary.main' : 'secondary.main') : 'text.primary'
                }}>
                    {winner === -1 ? `Player ${current === 1 ? 'X' : 'O'}'s Turn` :
                        winner === -2 ? "It's a Tie!" : `Winner: Player ${winner === 1 ? 'X' : 'O'}`}
                </Typography>

                <Stack alignItems="center" sx={{ mb: 4 }}>
                    {disp !== "" ? disp : <Typography color="text.secondary">Loading Board...</Typography>}
                </Stack>

                <Button
                    variant="contained" startIcon={<RefreshIcon />}
                    onClick={resetBoard} sx={{ borderRadius: 2, px: 4 }}
                >
                    Reset Game
                </Button>
            </Box>
        </Stack>
    );
}